begin;

-- Assignment creation in active_workspace is reward-neutral. Select the rule from
-- the mission row locked by the existing capacity UPDATE, so a concurrent mode
-- change cannot pick a stale XP rule. Legacy (including historical NULL) stays +10.
-- No existing balances, awarded XP, workflows or reward snapshots are rewritten.
create or replace function private.join_mission(p_mission uuid)
returns public.mission_submissions
language plpgsql security definer set search_path = public
as $$
declare
  v_creator uuid := auth.uid();
  v_ws uuid;
  v_level text;
  m record;
  v_rows int;
  v_mode text;
  v_join_xp integer;
  v_sub public.mission_submissions;
begin
  if v_creator is null then raise exception 'not_authenticated'; end if;

  select workspace_id, level into v_ws, v_level
    from public.creators where id = v_creator;
  if v_ws is null then raise exception 'not_found'; end if;

  select id, workspace_id, status, access_type, deadline, required_level, quota, filled
    into m from public.missions where id = p_mission;
  if m.id is null or m.workspace_id <> v_ws then raise exception 'not_found'; end if;
  if m.status <> 'active' then raise exception 'closed'; end if;
  if m.access_type <> 'open' then raise exception 'not_open'; end if;
  if m.deadline is not null and m.deadline < current_date then raise exception 'closed'; end if;

  -- Preserve the effective-level and verified-handle gates for L2+ missions.
  if public.level_ordinal(m.required_level) >= public.level_ordinal('L2') then
    if public.level_ordinal(v_level) < public.level_ordinal(m.required_level) then
      raise exception 'level_locked';
    elsif not exists (
      select 1 from public.creator_social_accounts
      where creator_id = v_creator and owner_verified
    ) then
      raise exception 'verification_required';
    end if;
  elsif public.level_ordinal(v_level) < public.level_ordinal(m.required_level) then
    raise exception 'level_locked';
  end if;

  if exists (select 1 from public.mission_submissions
             where mission_id = p_mission and creator_id = v_creator)
    then raise exception 'already_joined'; end if;

  update public.missions set filled = filled + 1
    where id = p_mission and filled < quota
    returning creator_workflow_mode into v_mode;
  get diagnostics v_rows = row_count;
  if v_rows = 0 then raise exception 'mission_full'; end if;
  v_join_xp := case when v_mode = 'active_workspace' then 0 else 10 end;

  begin
    insert into public.mission_submissions
      (mission_id, creator_id, workspace_id, status, xp_awarded)
      values (p_mission, v_creator, v_ws, 'joined', v_join_xp)
      returning * into v_sub;
  exception when unique_violation then
    raise exception 'already_joined';
  end;
  if v_join_xp > 0 then
    update public.creators set xp = xp + v_join_xp where id = v_creator;
  end if;
  return v_sub;
end;
$$;

-- Both the service-only primitive and decide_mission_application dispatch here.
-- Preserve its submission lock, idempotent joined return and atomic quota guard.
-- Active acceptance only changes status: prior earned XP must never be removed.
create or replace function public.accept_application(p_submission uuid)
returns public.mission_submissions
language plpgsql security definer set search_path = public
as $$
declare
  v_sub public.mission_submissions;
  v_rows int;
  v_mode text;
begin
  select * into v_sub from public.mission_submissions where id = p_submission for update;
  if v_sub.id is null then raise exception 'not_found'; end if;
  if v_sub.status = 'joined' then return v_sub; end if;
  if v_sub.status <> 'applied' then raise exception 'wrong_state'; end if;

  update public.missions set filled = filled + 1
    where id = v_sub.mission_id and filled < quota
    returning creator_workflow_mode into v_mode;
  get diagnostics v_rows = row_count;
  if v_rows = 0 then raise exception 'mission_full'; end if;

  if v_mode = 'active_workspace' then
    update public.mission_submissions set status = 'joined'
      where id = p_submission returning * into v_sub;
  else
    update public.mission_submissions set
      status = 'joined', xp_awarded = xp_awarded + 10
      where id = p_submission returning * into v_sub;
    update public.creators set xp = xp + 10 where id = v_sub.creator_id;
  end if;
  return v_sub;
end;
$$;

